// Build the Set — single source of truth, server-side only
const WORD_LIST = new Set(
    WORDS.map(w => w.toLowerCase().trim()).filter(w => w.length > 3)
);

// Build pair → answers map
// e.g. { "ae": ["able","alive",...], "ak": ["awake",...], ... }
const pairAnswers = {};
for (const word of WORD_LIST) {
    const key = word[0] + word[word.length - 1];
    if (!pairAnswers[key]) pairAnswers[key] = [];
    pairAnswers[key].push(word);
}

const VALID_PAIRS = Object.keys(pairAnswers);

module.exports = { WORD_LIST, pairAnswers, VALID_PAIRS };


// ═══════════════════════════════════════════════════════════════
//  DIFFICULTY TIERS
//  Classified by number of valid answers per pair
//  Easy: 15+ words, Medium: 7–14, Hard: 1–6
// ═══════════════════════════════════════════════════════════════
const EASY_PAIRS = [];
const MEDIUM_PAIRS = [];
const HARD_PAIRS = [];

for (const [key, answers] of Object.entries(pairAnswers)) {
    const count = answers.length;
    if (count >= 15) EASY_PAIRS.push(key);
    else if (count >= 7) MEDIUM_PAIRS.push(key);
    else HARD_PAIRS.push(key);
}

module.exports = { WORD_LIST, pairAnswers, VALID_PAIRS, EASY_PAIRS, MEDIUM_PAIRS, HARD_PAIRS };